const ITall={};Object.keys(IT).forEach(w=>IT[w].forEach(i=>{ITall[i.id]=Object.assign({w},i)}));
const inv=M=>M.wi=M.wi||{};
window.wShop=function(){const M=S&&S.mw;if(!M)return;const w=wOf(M),L=IT[w];if(!L||M.kid)return toast('ชีวิตนี้ยังไม่มีร้านของโลก');const I=inv(M);
 modal(`<button class="xbtn" onclick="closeM()">✕</button><h3>${WN[w][0]} ร้านของ${WN[w][1]}</h3><p class="tag2">ของที่หาได้เฉพาะในโลกนี้ · 🔁 ใช้ได้ = กดใช้เมื่อต้องการ · ♾️ ติดตัว = ได้ผลทุกปีอัตโนมัติ (ซื้อได้ชิ้นเดียว)</p><div class="mgrid">${L.map(i=>{const n=I[i.id]||0,own=i.t==='pas'&&n>0;return`<div class="item"><b>${i.ic} ${i.n}</b> <span class="tag2">${i.t==='pas'?'♾️ ติดตัว':'🔁 ใช้ได้'}${n&&i.t==='use'?' · มี '+n:''}</span><br><span class="tag2">${i.d}</span><div style="display:flex;gap:6px;margin-top:6px">${own?'<span class="tag2">✅ มีแล้ว</span>':`<button class="gbtn" onclick="wBuy('${i.id}')">ซื้อ ${price(M,i.p)}</button>`}${i.t==='use'&&n?`<button class="pbtn" onclick="wUse('${i.id}')">ใช้</button>`:''}</div></div>`}).join('')}</div>`,'wshop')};
window.wBuy=function(id){const M=S&&S.mw,i=ITall[id];if(!M||!i)return;const c=money(M,i.p),I=inv(M);if(i.t==='pas'&&I[id])return;if(S.money<c)return toast('เงินไม่พอ');S.money-=c;I[id]=(I[id]||0)+1;try{sfx('good')}catch(e){}log(`${i.ic} ได้ <b>${i.n}</b> มาไว้ในครอบครอง`,'good');try{island({ic:i.ic,h:'ได้ของเฉพาะโลก',t:i.n+' · อยู่ใน ☰ เมนู → ร้านของโลก',kind:'gold'})}catch(e){}render();saveGame();wShop()};
window.wUse=function(id){const M=S&&S.mw,i=ITall[id],I=inv(M||{});if(!M||!i||!I[id])return;I[id]--;const t=i.u(M);log(`${i.ic} ใช้ ${i.n} — ${t}`,'good');render();saveGame();wShop()};
const giveIt=(M,id)=>{const i=ITall[id];if(!i)return'';const I=inv(M);if(i.t==='pas'&&I[id])return'';I[id]=(I[id]||0)+1;return` · ได้ ${i.ic} ${i.n}`};

