Object.keys(LEG).forEach(k=>MW_R.push({id:'wh_'+k,w:0,cd:0,c:()=>false,go(M){const L=M.wleg;if(!L)return;M.wleg.done=1;LEG[k](M,L);if(L.gift){const i=ITall[L.gift];if(i)setTimeout(()=>log(`🎁 ของตกทอดจาก${esc(L.pn)}: <b>${i.ic} ${i.n}</b>`,'good',true),400)}}}));

