function thCand(M,w,out){const o=st(M,w);let v=null;if(o)v=o[SK[w][2]];else if(w==='hunter'&&M.H)v=M.H.trm||0;if(v==null)return;M.wth=M.wth||{};const T=M.wth[w]=M.wth[w]||[0,0,0];
 TH.forEach((t,i)=>{if(T[i]&&v<t-15)T[i]=0;if(!T[i]&&v>=t){out.push({id:'th_'+w+i,p:5+i,on:()=>{T[i]=1}})}})}
{const _y=mwYear;mwYear=function(){const foc=S&&S.focus;const r=_y.apply(this,arguments);try{const M=S&&S.mw;if(!M||!won(M))return r;const w=wOf(M);if(!CAND[w]&&w!=='hunter')return r;
 const out=[];thCand(M,w,out);if(CAND[w])CAND[w](M,foc,out);
 M._fq=M._fq||{};const RPT=/^(hx_mil|hx_gate|hx_th_gate|hx_daily|wu_jy|wg_case|al_mkY|hx_ownY|hx_ret|wu_turf|wu_def|wz_door|wz_life|hp_life|hx_ts|hx_as|al_gr|al_gg|hx_fam|hx_rogue|hx_vil|hx_bounty|hx_book|hx_cata|wl_clue)/;for(let i=out.length-1;i>=0;i--){const q=M._fq[out[i].id];if(q!=null&&M.y-q<2&&!RPT.test(out[i].id))out.splice(i,1)}out.sort((a,b)=>b.p-a.p);const n=out.length&&(out[0].p>=5||(out[1]&&out[1].p>=3&&out[1].id.slice(0,3)!==out[0].id.slice(0,3)))?2:1;out.slice(0,n).forEach(c=>{if(c.on)c.on();M._fq[c.id]=M.y;fire(c.id)})}catch(e){console.error(e)}return r}}

