const ROLE={doc:['🩺','หมอ'],eng:['🔧','ช่าง'],sol:['🪖','อดีตทหาร'],far:['🌾','ชาวนา'],kid:['🧒','เด็ก'],tea:['📚','ครู']};
const zI=M=>{const Z=M.Z;if(Z.sup==null)Z.sup=20;Z.com=Z.com||[];Z.rd=Z.rd||0;return Z};
const zDef=(M,Z)=>Math.round(Z.surv/3+(has(M,'fence')?15:0)+Z.com.filter(c=>c.r==='sol').length*12+Z.com.filter(c=>c.r==='eng').length*6+(has(M,'bat')?5:0));
const zAddC=(M,r)=>{const Z=zI(M),n=nm();Z.com.push({n,r:r||ch(Object.keys(ROLE))});return Z.com[Z.com.length-1]};
CAND.zombie=(M,foc,out)=>{const Z=zI(M);
 const need=5+Z.com.length*3-Z.com.filter(c=>c.r==='far').length*4;let get=R(1,5)+(foc==='wxz'?Math.round(R(7,13)*(1+Z.rk*.12)):0)+(foc==='wxb'?R(0,3):0);Z.sup+=get-Math.max(0,need);
 if(Z.com.some(c=>c.r==='doc'))Z.inf=Math.max(0,Z.inf-3);
 addFeed('ev',`🥫 เสบียง +${get} · ใช้ไป ${Math.max(0,need)} (คนในที่พัก ${Z.com.length+1} คน) · คงเหลือ <b>${Math.max(0,Z.sup)}</b>`,'sum');
 if(Z.sup<0){Z.sup=0;const d=HP(R(10,20));joy(-6);addFeed('ev',`🍂 เสบียงไม่พอ ทุกคนอดมื้อกินมื้อ พลังชีวิต −${d}`,'sum');if(Z.com.length&&Math.random()<.5){const c=Z.com.splice(R(0,Z.com.length-1),1)[0];addFeed('ev',`🚶 ${esc(c.n)} (${ROLE[c.r][1]}) ทิ้งที่พักไปหาที่ที่มีของกินมากกว่า`,'sum')}}
 if(M.y-(Z.rdY||0)>=R(4,5)&&M.y>=3)out.push({id:'wz_raid',p:4});
 if(Z.com.length<8&&Math.random()<.35)out.push({id:'wz_door',p:1});
 if(Z.com.length&&Math.random()<.3)out.push({id:'wz_life',p:1});
 if(due(M,'zrv',0,2)&&Z.surv>=20)out.push({id:'wz_rv0',p:2});else if(due(M,'zrv',1,3))out.push({id:'wz_rv1',p:3});else if(due(M,'zrv',2,4)&&Z.surv>=60)out.push({id:'wz_rv2',p:4})};
EV('wz_door',M=>{const Z=zI(M),r=ch(Object.keys(ROLE)),n=nm(),txt={doc:'ผู้หญิงในชุดพยาบาลเปื้อนเลือด แบกกระเป๋ายามาด้วย',eng:'ชายมือหยาบเต็มไปด้วยรอยไหม้ มีกล่องเครื่องมือหนักอึ้ง',sol:'ชายหนุ่มในชุดพรางขาดวิ่น ปืนไม่มีกระสุนแล้ว',far:'หญิงชราแบกถุงเมล็ดพันธุ์สองถุงใหญ่',kid:'เด็กหญิงตัวเล็กยืนกอดตุ๊กตาอยู่คนเดียว ไม่พูดสักคำ',tea:'ครูวัยกลางคนพาเด็กนักเรียนสามคนมาด้วย'}[r];
 choice('🚪 มีคนเคาะประตู',`<b>${esc(n)}</b> — ${txt} ขอเข้ามาอยู่ด้วย ทุกคนในที่พักหันมามองคุณ (เสบียงตอนนี้ ${Z.sup})`,[
 O('เปิดประตูรับ',()=>{if(Math.random()<.12){Z.inf=cl(Z.inf+20,0,100);say(`🩸 ${esc(n)}มีแผลกัดซ่อนอยู่ใต้แขนเสื้อ คุณจัดการทันก่อนจะลาม แต่ทุกคนในที่พักเห็น`,'bad',{joy:-8})}else{Z.com.push({n,r});say(`🤝 ${esc(n)} (${ROLE[r][0]} ${ROLE[r][1]}) เข้าร่วมที่พัก`,'good')}},'~12% แอบติดเชื้อ'),
 O('ตรวจร่างกายก่อนให้เข้า',()=>{Z.com.push({n,r});joy(-2);say(`🔦 ตรวจละเอียดจนเขาอาย แต่ปลอดภัย ${esc(n)}เข้าร่วมที่พัก`,'good')}),
 O('ให้เสบียงแล้วส่งไป',()=>{Z.sup=Math.max(0,Z.sup-5);say('🥫 คุณยื่นกระป๋องห้ากระป๋องผ่านช่องประตู เขาพยักหน้าแล้วเดินหายไปในความมืด','')}),
 O('ไม่เปิด',()=>{joy(-5);say('🚪 เสียงเคาะเบาลงเรื่อยๆ จนเงียบ คุณไม่กล้าเปิดดูตอนเช้า','bad')})])});
