const ELN=['ไฟ','น้ำแข็ง','สายฟ้า','ลม','ดิน'];
const pickCl=(n,legBoost)=>{const ks=Object.keys(CL),out=[];for(let i=0;i<n;i++){let t=ks.reduce((a,k)=>a+(out.includes(k)?0:CL[k].w*(CL[k].leg&&legBoost?4:1)),0)*Math.random();for(const k of ks){if(out.includes(k))continue;t-=CL[k].w*(CL[k].leg&&legBoost?4:1);if(t<=0){out.push(k);break}}}return out};
const skN=(H,i)=>{const c=CL[H.cls];let n=c.sk[i];if(c.el&&H.el)n=n.replace('ธาตุ',H.el);return n};
const skLv=(H,i)=>(H.sk||{})[i]||0;
const bestSk=H=>{const k=Object.keys(H.sk||{}).map(Number).sort((a,b)=>H.sk[b]-H.sk[a]);return k.length?k[0]:0};
const skUp=(M,i,n)=>{const H=M.H;H.sk=H.sk||{};const a=H.sk[i]||0;H.sk[i]=Math.min(10,a+n);if(H.sk[i]>a)H.pw=(H.pw||0)+(H.sk[i]-a)*12};

