{const _a=hwAwaken;hwAwaken=function(M){const r=_a.apply(this,arguments);try{if(M&&HI(M)&&M.H.aw==='none'&&Math.random()<.45){M.H.aw='aw';M.H.pw=R(60,400);mwSay('⚡ ในโลกที่พลังล้นทะลักจากเกตทุกวัน ร่างกายคุณก็ไม่รอดเช่นกัน <b>คุณตื่นพลังแล้ว</b>','epic',{joy:6},true)}}catch(e){}return r}}
