const syI=H=>H.sy=H.sy||{lv:1,xp:0,pts:0,pen:0,q:0};
const syXP=(M,n)=>{const H=M.H,Y=syI(H);Y.xp+=n;let up=0;while(Y.xp>=Y.lv*10){Y.xp-=Y.lv*10;Y.lv++;Y.pts+=3;up++}if(up){log(`🟦 <span class="px">[เลเวลอัป! Lv.${Y.lv}]</span> ได้แต้มค่าสถานะ +${up*3} แจกได้ที่ 🪪 บัตรฮันเตอร์`,'myth',true);try{island({ic:'🟦',h:'เลเวลอัป',t:'Lv.'+Y.lv+' · แต้ม +'+up*3,kind:'gold'})}catch(e){}if(Y.lv>=100)M.fl.hSys=1}};

