const C0=CAND.hunter;
CAND.hunter=(M,foc,out)=>{C0(M,foc,out);const H=M.H;if(H&&H.no&&H.aw&&H.aw!=='none'&&Math.random()<.15)out.push({id:'hx_reg',p:3});if(!H||H.no)return;
 if(H.cls&&H.r>=0&&!HI(M)){if(H.rLast==null)H.rLast=H.r;if(H.r>H.rLast){H.rLast=H.r;unlockSk(M)}}
 if(HI(M))for(let i=out.length-1;i>=0;i--)if(out[i].id==='hp_exam')out.splice(i,1);
 if(H.aw&&H.aw!=='none'&&!H.cls)out.push({id:'hx_cls',p:8});
 if(H.r<0||!H.cls)return;
 if(HI(M)&&H.rx==null){out.push({id:'hx_rank',p:9});return}
 // ตลาดหินมานา
 H.mkt=cl(Math.round((H.mkt||100)*(1+(Math.random()-.5)*.5)),40,260);
 if(H.aw==='sys'&&Math.random()<.7)out.push({id:'hx_daily',p:3});
 if(foc==='mwgate'&&Math.random()<.75)out.push({id:'hx_gate',p:3});
 if(CL[H.cls].leg&&H.cls==='eat'){H.hun=cl((H.hun||0)+R(3,7),0,100);if(H.hun>=70&&Math.random()<.5)out.push({id:'hx_hunger',p:5})}
 if(HI(M)){const t=RX_T.findIndex((v,i)=>i===RX_T.length-1||pow(M)<RX_T[i+1]);if(t>H.rx&&!H.hide&&M.y-(H.exY||-9)>=2)out.push({id:'hx_exam',p:4});
  if(H.rx<=5&&S.age>=22&&!H.aw2&&Math.random()<.025)out.push({id:'hx_aw2',p:6});
  if(H.rx>=6&&!M.fl.hx_s)out.push({id:'hx_s',p:5});if(H.rx>=7&&!M.fl.hx_ss)out.push({id:'hx_ss',p:5});if(H.rx>=8&&!M.fl.hx_sss)out.push({id:'hx_sss',p:7});
  if(H.rx>=8&&syI(H).lv>=60&&H.aw==='sys'&&!M.fl.hEX)out.push({id:'hx_ex',p:8});
  if(H.rx>=4&&Math.random()<.12)out.push({id:'hx_cata',p:4})}
 const rr=HI(M)?H.rx:H.r+1;
 if(!H.gd2&&rr>=2&&Math.random()<.5)out.push({id:'hx_guild',p:3});
 if(H.gd2==='big'&&Math.random()<.25)out.push({id:'hx_order',p:2});
 if(H.gd2!=='own'&&rr>=4&&(S.money||0)>money(M,30)&&!H.ownAsk&&Math.random()<.3)out.push({id:'hx_own',p:3});
 if(H.gd2==='own'&&Math.random()<.35)out.push({id:'hx_ownY',p:2});
 if(Math.random()<.14)out.push({id:H.vil?'hx_vil':'hx_rogue',p:2});
 if(!H.vil&&rr>=2&&Math.random()<.12)out.push({id:'hx_bounty',p:1});
 if((H.skn||0)<5&&Math.random()<.18)out.push({id:'hx_book',p:1});
 if(CL[H.cls].pet&&!H.pet)out.push({id:'hx_pet',p:3})};

EV('hx_reg',M=>{const H=M.H;choice('🏛️ สมาคมยังรอคุณอยู่','จดหมายจากสมาคมฮันเตอร์มาถึงอีกฉบับ "ผู้ตื่นพลังที่ไม่ลงทะเบียนยังเข้าสอบได้ทุกเมื่อ" ข้างนอกยังมีเกตแตกทุกสัปดาห์',[
 O('ไปลงทะเบียน',()=>{H.no=0;H.r=hRank(hStr(M));say(`🪪 ช้ากว่าคนอื่นหลายปี แต่บัตรฮันเตอร์ใบนี้เป็นของคุณแล้ว แรงก์ ${HR[H.r]}`,'epic');keyAdd('ลงทะเบียนฮันเตอร์')}),
 O('ใช้ชีวิตพลเรือนต่อ',()=>say('🏠 พลังที่ไม่ได้ใช้ยังอยู่ในตัวคุณเงียบๆ',''))])});
// ---------- รับสายพลัง ----------
EV('hx_cls',M=>{const H=M.H,leg=H.aw==='sys'||HI(M);const ks=pickCl(H.aw==='sys'?3:2,leg);
 choice('🔮 สายพลังคุณ',`เครื่องตรวจวัดของสมาคมพิมพ์ผลออกมา${ks.length}แนวที่ร่างกายคุณรับได้ เลือกพัฒนาได้แนวเดียว และจะเป็นตัวคุณไปตลอดชีวิต${H.aw==='sys'?' <span class="px">[ระบบ: โฮสต์เลือกได้ 3 แนว]</span>':''}`,ks.map(k=>{const c=CL[k];return O(`${c.ic} ${c.n}${c.leg?' ✦ตำนาน':''}`,()=>{H.cls=k;if(c.el)H.el=ch(ELN);Object.keys(c.st).forEach(s=>stUp(M,s,c.st[s]));H.sk={0:1};H.skn=1;say(`${c.ic} <b>สายพลัง: ${c.n}${H.el?' ('+H.el+')':''}</b> — สกิลแรก <b>${skN(H,0)}</b> ตื่นขึ้นในร่างคุณ`,c.leg?'myth':'epic');keyAdd('ตื่นพลังสาย'+c.n);if(c.leg)M.fl['hcl_'+k]=1},c.d)}))});
// ---------- วัดแรงก์ F–SSS ----------
EV('hx_rank',M=>{const H=M.H;let p=pow(M),b=0;RX_T.forEach((t,i)=>{if(p>=t)b=i});const roll=()=>{let t=RX_P.reduce((a,v)=>a+v,0)*Math.random();for(let i=0;i<RX_P.length;i++){t-=RX_P[i];if(t<=0)return i}return 0};
 let x=Math.max(b,roll());if(H.aw==='sys')x=Math.min(8,x+R(0,2));if(CL[H.cls].leg)x=Math.min(8,x+1);
 const show=()=>{H.rx=x;H.r=rxToR(x);H.pw=Math.max(H.pw||0,RX_T[x]-mwStr(M)+R(0,60));const cm=['สายตาสงสาร','ไม่มีใครเงยหน้า','เจ้าหน้าที่พยักหน้าเฉยๆ','มีคนหันมามองสองสามคน','กิลด์กลางเริ่มทักมา','ทั้งชั้นหันมามอง','ผู้อำนวยการสมาคมลงมาดูด้วยตัวเอง','เจ้าหน้าที่โทรรายงานกระทรวงกลาโหมทันที','เครื่องวัดระเบิด ทั้งตึกอพยพ ข่าวด่วนทุกช่องทั่วโลก'][x];
  say(`🪪 ผลวัดแรงก์: <b style="font-size:1.2em">${RX[x]}</b> — ${cm}`,x>=6?'myth':x>=4?'epic':x<=1?'bad':'');keyAdd('ได้แรงก์ '+RX[x]);if(x>=6)mwFx({fame:[0,0,0,0,0,0,20000,80000,300000][x]})};
 choice('📡 ห้องวัดแรงก์ของสมาคม',`คุณวางมือลงบนลูกแก้วตรวจวัด ตัวเลขบนจอวิ่งขึ้นเรื่อยๆ ทุกคนในห้องเงียบ… ${H.aw==='sys'?'<span class="px">[ระบบ: ต้องการให้ซ่อนค่าพลังจริงหรือไม่]</span>':''}`,[
  O('ปล่อยพลังเต็มที่',show),
  O('กดพลังไว้ ให้วัดได้แค่ F',()=>{H.rxHid=x;x=0;H.hide=1;show();H.rxTrue=H.rxHid;say('🤫 ทุกคนในห้องเลิกสนใจคุณทันที และนั่นคือสิ่งที่คุณต้องการ','')},'ซ่อนพลังจริง · เปิดเผยทีหลังได้')])});
// ---------- เควสรายวันของระบบ ----------
const DQ=['วิดพื้น 100 · ซิทอัพ 100 · สควอต 100 · วิ่ง 10 กม.','ล่าก็อบลินในเกต F ให้ครบ 30 ตัว','นั่งสมาธิดูดซับมานา 3 ชั่วโมง','ช่วยคนแปลกหน้า 1 คนโดยไม่ให้ใครรู้','ฝึกสกิลเดียวซ้ำ 1,000 ครั้ง'];
EV('hx_daily',M=>{const H=M.H,Y=syI(H),q=ch(DQ);choice('🟦 [เควสรายวัน]',`<span class="px">[ภารกิจประจำวัน: ${q}]</span><br>[รางวัล: ค่าประสบการณ์ · แต้มค่าสถานะ] [บทลงโทษเมื่อล้มเหลว: ย้ายไปยังเขตลงโทษ]<br>Lv.${Y.lv} · แต้มคงเหลือ ${Y.pts}`,[
 O('ทำครบทุกวันทั้งปี',()=>{syXP(M,R(18,30));Y.q++;if(Y.q%5===0){skUp(M,bestSk(H),1);say(`🟦 <span class="px">[ทำเควสรายวันครบ ${Y.q} ปี — รางวัลพิเศษ: ${skN(H,bestSk(H))} Lv.+1]</span>`,'myth')}else say('🟦 ร่างกายเจ็บระบมทุกเช้า แต่ตัวเลขในหน้าต่างสถานะขึ้นทุกวัน','good');HP(5)}),
 O('ทำบ้าง ข้ามบ้าง',()=>{syXP(M,R(6,12));if(Math.random()<.3)later(()=>fire('hx_pen'));else say('🟦 ระบบส่งข้อความเตือนสีแดงสองครั้ง','')},'~30% โดนลงโทษ'),
 O('เมินเควสทั้งหมด',()=>later(()=>fire('hx_pen')))])});
