// เกต: เลือกเกต → เลือกวิธีบุก
// ============================================================
const GT={normal:['🚪','เกตธรรมดา','มอนสเตอร์เต็มทุกห้อง บอสรออยู่ห้องสุดท้าย'],red:['🔴','เกตสีแดง','ประตูปิดตายหลังทุกคนเข้าไป ต้องหาทางออกเอง หรือฆ่าบอสให้ได้'],break:['🟣','ดันเจี้ยนเบรก','มอนสเตอร์ทะลักออกมาในเมืองแล้ว ประชาชนยังอพยพไม่หมด'],treasure:['🟡','เกตสมบัติ','มอนสเตอร์น้อย ของมีค่าเยอะ ทุกกิลด์แย่งกันเข้า'],spirit:['👻','เกตวิญญาณ','อาวุธทั่วไปฟันไม่เข้า สิ่งที่อยู่ข้างในคือผี'],illusion:['🌫️','เกตภาพลวง','ทางเดินเปลี่ยนเองทุกนาที เพื่อนร่วมทีมอาจไม่ใช่ตัวจริง'],boss:['💀','เกตบอสเดี่ยว','ทั้งเกตมีมอนสเตอร์ตัวเดียว ใหญ่เท่าตึก']};
const gReq=(M,g)=>HI(M)?RX_T[g]*1.1+60:HR_T[Math.min(5,g)]*1.1+50;
const gNm=(M,g)=>HI(M)?RX[g]:HR[Math.min(5,g)];
const gMax=M=>HI(M)?8:5;
const gP=(M,g,bonus)=>{const s=pow(M),q=gReq(M,g);return cl(s/(s+q)*1.3+(bonus||0)+((M.H.pt||[]).length*.03),.05,.95)};
EV('hx_gate',M=>{const H=M.H,cur=HI(M)?H.rx:H.r,mx=gMax(M);const gs=[];for(let i=0;i<3;i++){const g=cl(cur+R(-1,2)+(i===2?1:0),0,mx),t=ch(Object.keys(GT));gs.push({g,t})}
 choice('🌀 กระดานเกตของสมาคม',`ปีนี้มีเกตเปิดให้ลงชื่อ (พลังคุณ ${pow(M)} · แรงก์ ${rkName(M)})`,gs.map(x=>{const T=GT[x.t],p=gP(M,x.g,(CL[H.cls].b||{})[x.t]||0);return O(`${T[0]} ${T[1]} เกรด ${gNm(M,x.g)}`,()=>later(()=>gateGo(M,x.g,x.t),350),`${T[2]} · โอกาสรอด ~${Math.round(p*100)}%`)}).concat([O('ไม่ลงเกตปีนี้',()=>{H.trm=Math.max(0,(H.trm||0)-6);say('🛋️ คุณดูข่าวการปิดเกตจากโซฟา','')})]))});
function gateGo(M,g,t){const H=M.H,T=GT[t],cb=(CL[H.cls].b||{})[t]||0,base=gP(M,g,cb),bi=bestSk(H),bl=skLv(H,bi),ms=Math.round((g+1)*(g+1)*R(2,5)*(HI(M)?1.6:1));
 const win=(mult,txt)=>{const m=Math.round(ms*mult);H.ms=(H.ms||0)+m;H.mp=(H.mp||0)+R(1,3)+g;H.def=(H.def||0)+1;H.trm=cl((H.trm||0)+R(2,6),0,100);const ks=Object.keys(H.st||{});stUp(M,ch(ks.length?ks:['str']),R(1,2)+Math.floor(g/3));if(Math.random()<.6)skUp(M,ch(Object.keys(H.sk||{0:1}).map(Number)),1);if(H.aw==='sys')syXP(M,6+g*4);mwFx({fame:(g+1)*(g+1)*120});if(H.cls==='eat'){stUp(M,'str',1);H.hun=Math.max(0,(H.hun||0)-12)}if(CL[H.cls].pet&&H.pet)H.pet.lv=(H.pet.lv||1)+1;say(`${T[0]} ${txt} · หินมานา +${m} · ชิ้นส่วน +${R(1,3)+g}`,'epic')};
 const lose=(d,txt)=>{H.trm=cl((H.trm||0)+R(8,15),0,100);if((H.pt||[]).length&&Math.random()<.25){const c=H.pt.splice(R(0,H.pt.length-1),1)[0];txt+=` · ${esc(c.n)}ไม่ได้ออกมาด้วย`;M.fl.hlost=1;joy(-10)}if(g>=(HI(M)?H.rx:H.r)+2&&Math.random()<.12)return die([`เสียชีวิตในเกตเกรด ${gNm(M,g)}`],`☠️ <b>${T[1]}เกรด ${gNm(M,g)} ปิดลงพร้อมคุณอยู่ข้างใน…</b>`);say(`🩸 ${txt} พลังชีวิต −${HP(d)}`,'bad')};
 const os=[O(`⚔️ บุกตรง`,()=>Math.random()<base?win(1,'ฝ่าทุกห้องจนถึงบอส เกตปิดลงข้างหลังคุณ'):lose(25,'มอนสเตอร์เยอะกว่าที่ประเมิน'),`~${Math.round(base*100)}%`),
  O(`${CL[H.cls].ic} ใช้ ${skN(H,bi)} Lv.${bl}`,()=>{const p=cl(base+bl*.035,.05,.97);Math.random()<p?(skUp(M,bi,1),win(1.15,`${skN(H,bi)}เปลี่ยนเกมทั้งเกต`)):lose(22,`${skN(H,bi)}ใช้ไม่ทันจังหวะ`)},`~${Math.round(cl(base+bl*.035,.05,.97)*100)}% · สกิลโตขึ้น`),
  O('👁️ สอดแนมก่อนแล้วค่อยบุก',()=>{const p=cl(base+.12+(H.st.sen||0)/400,.05,.97);Math.random()<p?win(.7,'แผนรัดกุม ไม่มีใครเจ็บ'):lose(12,'สอดแนมแล้วก็ยังพลาด')},`~${Math.round(cl(base+.12+((H.st&&H.st.sen)||0)/400,.05,.97)*100)}% · ของน้อยลง`)];
 if(t==='break')os.push(O('🚑 อพยพประชาชนก่อน ทิ้งของ',()=>{mwFx({fame:(g+1)*(g+1)*400,joy:6});H.trm=cl((H.trm||0)+5,0,100);say('🚑 ประชาชนรอดทั้งหมด ข่าวภาคค่ำเปิดภาพคุณอุ้มเด็กออกจากซากตึก','myth');M.fl.hHero=(M.fl.hHero||0)+1}));
 if(t==='treasure')os.push(O('🎒 แอบเก็บของก่อนทีมอื่น',()=>{if(Math.random()<.5+((CL[H.cls].b||{}).treasure||0)){H.ms=(H.ms||0)+ms*2;say(`💎 กระเป๋าคุณหนักกว่าทุกคนในทีม · หินมานา +${ms*2}`,'epic')}else{(H.pt||[]).forEach(x=>x.tr-=15);say('😬 เพื่อนร่วมทีมจับได้ คุณต้องคืนของทั้งหมดและเสียความไว้ใจ','bad')}}));
 if(t==='red')os.push(O('🗝️ หาทางออกลับ',()=>{const p=cl(.35+(H.st.sen||0)/150+((CL[H.cls].b||{}).red||0),.05,.95);Math.random()<p?(H.mp=(H.mp||0)+g*2,say('🗝️ คุณพบประตูลับหลังรูปปั้นบอส ทั้งทีมออกมาได้โดยไม่ต้องสู้','good')):lose(30,'ทางออกลับเป็นกับดัก')}));
 if(t==='spirit')os.push(O(H.cls==='shaman'?'📿 ผนึกด้วยสายสิญจน์':'🙏 ท่องบทสวดที่ยายสอน',()=>{const p=H.cls==='shaman'?.9:.3;Math.random()<p?win(1.3,'วิญญาณทุกดวงสงบลงและจากไป'):lose(20,'บทสวดไม่ได้ผลกับสิ่งนี้')},H.cls==='shaman'?'~90%':'~30%'));
 if(t==='illusion')os.push(O('🧠 ไม่เชื่อสิ่งที่ตาเห็น',()=>{const p=cl(.3+(H.st.sen||0)/120+((CL[H.cls].b||{}).illusion||0),.05,.95);Math.random()<p?win(1.1,'คุณหลับตาเดินตามเสียงหัวใจของบอส จนหาตัวจริงเจอ'):lose(18,'คุณฟันเพื่อนร่วมทีมที่คิดว่าเป็นภาพลวง')}));
 os.push(O('🏃 ถอนตัว',()=>{H.trm=Math.max(0,(H.trm||0)-3);say('🚪 คุณถอนตัวตั้งแต่ห้องแรก บางคนหัวเราะ บางคนรอดเพราะตามคุณออกมา','')}));
 choice(`${T[0]} ${T[1]} เกรด ${gNm(M,g)}`,T[2]+` · พลังที่แนะนำ ~${Math.round(gReq(M,g))} (คุณ ${pow(M)})`,os)}

