const BASE={r:46,s:72,b:76},DEC={r:6,s:5,b:4};
function chance(M,D,si,k){const N=nI(M);let p=BASE[k]-si*DEC[k];
 const skv=D.sk==='hp'?(S.hp/S.maxHp-.7)*50:((+S[D.sk]||0)-(D.sk==='cha'?15:30));p+=cl(skv/4,-8,10);
 p+=Math.min(12,nbOk(M)*4)+(N.adv?8:0)-(N.pr>60?Math.round((N.pr-60)/2.5):0)-(S.money<money(M,1)?5:0);return cl(Math.round(p),12,90)}
