const GCL={war:['⚔️','นักรบ','เลเวลขึ้นเร็วกว่า'],mage:['🔮','นักเวท','ชนะบอสง่ายกว่า'],craft:['🔨','ช่างคราฟต์','หาเงินจากสกิลได้มาก'],rogue:['🗡️','โจร','รอดจาก PK ง่าย']};
