CAND.game=(M,foc,out)=>{if(!on(M,'game'))return;const G=qI(M),r=Math.random;if(G.free)return;
 if(!G.cls)out.push({id:'wi_game',p:5});
 if(G.lv>=60&&!G.fin&&M.y-G.fy>=2)out.push({id:'g_final',p:5});
 if(r()<.1)out.push({id:'g_pk',p:1.8});
 if(!G.ms.bug&&G.lv>=8&&r()<.08)out.push({id:'g_bug',p:2});
 if(!G.ms.gd&&G.lv>=15&&r()<.12)out.push({id:'g_guild',p:2});
 if(r()<.09)out.push({id:'g_hid',p:1.5});
 if(!G.ms.free&&G.lv>=30&&r()<.05)out.push({id:'g_free',p:1.7})};

