function gmSpec(M,tier){const G=G0(M),X=xI(M),L=SPC[G.cls];if(!L)return;
 choice(`⭐ ต้นสกิลแตกแขนง (เลเวล ${tier===1?20:40})`,tier===1?`คลาส${GCLN(G)}ของคุณมาถึงทางแยก เลือกได้ทางเดียว และเปลี่ยนไม่ได้อีก`:'ทางแยกที่สอง เลือกอีกทาง หรือเจาะลึกทางเดิมให้สุด',
  (tier===1?L:L.filter(x=>x[0]!==X.sp).concat([[X.sp+'+','💠','เจาะลึกทางเดิม','พลังของสายแรกแรงขึ้นอีกขั้น']])).map(s=>O(`${s[1]} ${s[2]}`,()=>{if(tier===1)X.sp=s[0];else X.sp2=s[0].replace('+','');say(`⭐ สายสกิล <b>${s[2]}</b> ถูกสลักลงในหน้าต่างสถานะ`,'epic')},s[3])))}
