{const _cd=checkDeath;checkDeath=function(){try{const M=S&&S.mw;if(on(M)&&gn(M)==='horror'&&S.alive){const Q=Y(M),H=Q.hr;const dying=S.age<75&&((S.hp<=0)||(S.deathCause&&!/ชรา|อายุขัย|แก่|โค้ด/.test(S.deathCause)));
  if(dying&&H.sv>0){H.sv--;S.deathCause=null;S.hp=Math.round(S.maxHp*.6);const ls=LOSS.filter(x=>!H.lost.includes(x));const l=ls.length?ch(ls):'เงาของคุณ';H.lost.push(l);lk(M,10,'ย้อนจุดเซฟ');
   log(`🕯️ <b>GAME OVER</b> <i>กำลังโหลดจุดเซฟ...</i> คุณสะดุ้งตื่นในวันที่เซฟไว้ ทุกอย่างเหมือนเดิม ยกเว้น <b>${l}</b> · จุดเซฟเหลือ ${H.sv}`,'myth',true);if(H.sv===0)M.fl.hr_last=1;return false}}}catch(e){console.error('b19 horror',e)}return _cd.apply(this,arguments)}}
