function rollTraits(M){if(M.TRT)return;const bg=M.native?((M.L&&M.L.bg)||(M.kid&&M.kid.bg)||''):'';const NO={orphan:['rich','star','care','poor'],farm:['rich','star'],single:['rich','star','twin','care'],mig2:['rich','star'],rich:['poor'],gov:['poor'],shop:[],mid:[]}[bg]||[];let ks=Object.keys(TRT).filter(k=>!NO.includes(k)&&(!M.native||k!=='orph'||bg==='orphan'));const n=bg==='orphan'?(Math.random()<.35?2:1):Math.random()<.35?2:1;const pick=bg==='orphan'?['orph']:[];let g=0;while(pick.length<n&&g++<60){const k=ch(ks);if(!pick.includes(k)&&!(k==='poor'&&pick.includes('rich'))&&!(k==='rich'&&pick.includes('poor'))&&!(k==='orph'&&pick.includes('care'))&&!(k==='care'&&pick.includes('orph')))pick.push(k)}
 M.TRT={k:pick,d:{}};pick.forEach(k=>{try{TRT[k][3](M)}catch(e){}});feed(`🎲 ${M.kid?'ชีวิตนี้เริ่มต้นแบบ':'ลักษณะชีวิตนี้'}: ${pick.map(k=>`<b>${TRT[k][0]} ${TRT[k][1]}</b>`).join(' · ')}`)}
window._rollTRT=rollTraits;Object.keys(TEV).forEach(k=>TEV[k].forEach((e,i)=>EV(`tt_${k}_${i}`,M=>{M.TRT.d[k+i]=1;choice(e[0],e[1],e[2].map(o=>O(o[0],()=>o[1](M))))})));

// ================= 2) 🧥 คนแปลกหน้าที่โผล่ทุกชีวิต =================
const GUISE={normal:'คนขับแท็กซี่ที่ไม่เปิดมิเตอร์',hunter:'ฮันเตอร์แรงก์ F ที่ไม่มีใครรู้ว่าลงเกตไปทำอะไร',under:'ชายแก่ที่นั่งดื่มชาหน้าบ่อนทุกคืน',ghost:'วิญญาณที่ไม่ยอมบอกว่าตายเมื่อไหร่',loop:'คนเดียวในเมืองที่ใส่เสื้อคนละตัวทุกรอบ',zombie:'ผู้รอดชีวิตที่ซอมบี้เดินผ่านเหมือนมองไม่เห็น',tower:'ลูกหาบที่แบกของขึ้นลงหอคอยมานานกว่าหอคอยมีอยู่',game:'NPC ที่พูดนอกบท',gatewon:'พ่อค้าที่เดินเข้าออกกำแพงได้โดยไม่มีใครเห็น',doom:'คนเดียวในเมืองที่ไม่กลัวอรุณ'};
const FRAG=['"เราเคยเจอกันแล้ว ในอีกโลกหนึ่ง เธอใส่เสื้อสีอื่น"','"ทุกโลกที่เธอเกิด ฉันอยู่ที่นั่นก่อนเสมอ"','"เธอคิดว่าโลกพวกนี้เกิดขึ้นเองเหรอ ฮันเตอร์ ซอมบี้ หอคอย"','"ทุกโลกเริ่มจากประโยคเดียว เขียนบนกระดาษแผ่นเดียว"','"ฉันเขียนให้เธอเกิดมาแล้วหลายร้อยครั้ง และเธอไม่เคยเลือกเหมือนเดิม"','"ตัวละครที่ดีที่สุด คือตัวที่คนเขียนคุมไม่ได้"','"หนังสือเล่มนี้ชื่อ หนึ่งในนวนิยาย เธอคือหนึ่งในนั้น"','"ปากกาอยู่ในมือฉันมานานเกินไปแล้ว"'];
const STR=()=>LG('murim_str',{n:0,w:{}});
EV('sx_meet',M=>{const T=STR(),w=wN(M),g=GUISE[w]||'คนแปลกหน้า',f=FRAG[Math.min(T.n,FRAG.length-1)];M._sx=1;
 choice('🧥 คนแปลกหน้าในเสื้อคลุมเทา',`${g} มองคุณแล้วยิ้มเหมือนรู้จักกันมานาน${T.n?`<br><span class="tag2">คุณเคยเจอเขามาแล้ว ${T.n} ครั้ง ใน ${Object.keys(T.w).length} โลก</span>`:''}`,[
  O('🗣️ ถามว่าเขาเป็นใคร',()=>{T.n++;T.w[w]=1;LSET('murim_str',T);say(`🧥 ${f}`,'myth');if(T.n>=FRAG.length&&Object.keys(T.w).length>=5)feed('🧥 <b>ครั้งหน้าที่เจอ เขาจะไม่หลบอีกแล้ว</b>')},'ได้เศษความจริงหนึ่งชิ้น'),
  O('👣 แอบตามไป',()=>{if(Math.random()<.5){T.n++;T.w[w]=1;LSET('murim_str',T);say(`👣 เขาเดินเข้าซอยตัน ตรงนั้นไม่มีใคร มีแต่กระดาษแผ่นหนึ่งเขียนว่า ${f}`,'myth')}else say(`👣 คุณตามไปจนหลง และตื่นมาที่บ้านตัวเอง พลังชีวิต −${HP(10)}`,'bad')},'อาจได้ อาจหลง'),
  O('🚶 เดินผ่านไป',()=>say('🚶 เขาไม่ได้ตาม แต่คุณรู้สึกว่าถูกมองตลอดทาง',''))])});
EV('sx_end',M=>{const T=STR();M._sx=1;
 choice('🧥 คนเขียน',`คราวนี้เขาไม่ได้ปลอมตัว เขานั่งรอบนเก้าอี้ไม้ตัวเดียวในห้องว่าง มีกองกระดาษสูงเท่าตึก ทุกแผ่นคือชีวิตหนึ่งของคุณ "ฉันคือคนเขียนนวนิยายเรื่องนี้ ทุกโลกที่เธอเคยอยู่ ฉันเขียนขึ้นมา และฉันเหนื่อยแล้ว"`,[
  O('🖊️ รับปากกามาเขียนต่อ',()=>{T.end='pen';LSET('murim_str',T);fl(M,'sx_pen');fx('ผู้เขียนคนใหม่','ทุกโลกหลังจากนี้ เขียนด้วยมือเธอ','#ffd34d');say('🖊️ ปากกาหนักกว่าที่คิด คุณเขียนประโยคแรก แล้วโลกทุกใบสั่นเบาๆ เหมือนหายใจ','myth',{fame:50000})}),
  O('📄 ฉีกหน้าสุดท้ายทิ้ง ปล่อยทุกตัวละครให้เป็นอิสระ',()=>{T.end='free';LSET('murim_str',T);fl(M,'sx_free');fx('ไม่มีหน้าสุดท้าย','ตัวละครทุกตัวเขียนตัวเองต่อจากนี้','#6fd8ff');say('📄 คนเขียนยิ้มทั้งน้ำตา "ฉันรอคนที่จะทำแบบนี้มานานมาก" แล้วจางหายไปพร้อมกระดาษทุกแผ่น','myth',{joy:30})}),
  O('🪑 นั่งลงข้างเขา ขอให้เขาเขียนต่อ แต่คราวนี้เขียนด้วยกัน',()=>{T.end='co';LSET('murim_str',T);fl(M,'sx_co');fx('ผู้เขียนร่วม','','#b48cff');say('🪑 เขาเลื่อนกระดาษมาให้ครึ่งหนึ่ง คืนนั้นทั้งสองคนเขียนจนเช้า','myth',{joy:20,fame:20000})})])});

