A('h_school',{w:'hunter',ic:'🏫',n:'เกตในโรงเรียนเก่า',st:M=>M.H&&!M.H.no&&S.age>=19,
 a0:['เกตในโรงเรียนประถมเก่า','เกตที่วัดเกรดไม่ได้เปิดขึ้นกลางสนามฟุตบอลของโรงเรียนประถมที่คุณเคยเรียน สมาคมสั่งปิดล้อม 48 ชั่วโมงเพื่อรอทีมแรงก์ S จากเมืองหลวง แต่กล้องวงจรปิดจับภาพได้ว่าเด็กสามคนวิ่งตามลูกบอลเข้าไปก่อนรั้วจะถูกตั้ง',[
  ['🗡️ ฝ่าแนวปิดล้อมเข้าไปเอง','ผิดกฎสมาคม','g'],['📋 รอคำสั่งตามกฎ','ปลอดภัยต่อใบอนุญาต','w'],['📡 ไลฟ์สด เรียกฮันเตอร์อิสระมาช่วย','วุ่นวายแน่','l']]],
 a1:{g:['ห้องเรียนที่หยุดเวลา','ข้างในเกตเป็นโรงเรียนคุณเมื่อยี่สิบปีก่อน กระดานดำยังมีชื่อคุณในเวรทำความสะอาด เด็กสามคนนั่งตัวสั่นอยู่ในห้องพักครู และสิ่งที่เฝ้าประตูมีหน้าเหมือนครูประจำชั้นคุณ',[['⚔️ สู้กับสิ่งที่ใส่หน้าครู','ปิดเกตจากข้างใน','f'],['🏃 พาเด็กหนีออกไปก่อน','ทิ้งเกตไว้','r']]],
  w:['ทีมแรงก์ S มาช้า','ทีมจากเมืองหลวงติดพายุ มาช้าไปสิบชั่วโมง เกตขยายจนกินอาคารเรียนไปครึ่งหลัง เมื่อทีมเข้าไปออกมา มีเด็กกลับมาสองคน',[['📢 ร้องเรียนสมาคมเรื่องกฎปิดล้อม','สู้ในระบบ','c'],['🔦 แอบกลับเข้าไปหาเด็กคนที่สาม','ผิดกฎซ้ำ','s']]],
  l:['ฮันเตอร์นับร้อยหน้ารั้ว','ไลฟ์มีคนดูล้านคน ฮันเตอร์อิสระมาถึงภายในชั่วโมง บางคนมาช่วย บางคนมาเพราะได้ยินว่าเกตที่วัดเกรดไม่ได้มักมีของหายาก ตำรวจเริ่มถอยเพราะคุมไม่อยู่',[['🧭 จัดทีมคนแปลกหน้าแล้วนำเข้าไปเอง','คุณคือคนเริ่มเรื่อง','t'],['✋ ขอให้ทุกคนถอย รอทีมของสมาคม','ใจเย็นที่สุด','b']]]},
 a2:{t:'ประตูของเกตโรงเรียน',x:{gf:'ครูมอนสเตอร์ยกไม้เรียวขึ้น เสียงที่ออกมาเป็นเสียงครูจริงๆ "เธอยังส่งการบ้านไม่ครบเลยนะ"',gr:'คุณอุ้มเด็กสองคน อีกคนเกาะหลัง ทางเดินยาวขึ้นเรื่อยๆ ทุกครั้งที่หันกลับไป',wc:'สมาคมเรียกคุณเข้าประชุมกรรมการ มีนักข่าวรออยู่หน้าห้อง และพ่อแม่ของเด็กคนที่สามนั่งแถวหน้า',ws:'คุณเจอเด็กคนที่สามนั่งอยู่บนชิงช้าในเกต เขาบอกว่า "ครูบอกให้รอตรงนี้" แกนเกตเต้นอยู่หลังชิงช้า',lt:'ทีมคนแปลกหน้าสิบสองคนยืนรอคำสั่งคุณหน้าประตูเกต ไม่มีใครรู้จักชื่อกันเลย',lb:'ฮันเตอร์บางกลุ่มไม่ยอมถอย และเริ่มตัดรั้วเข้าไปเอง'},
  risk:['ลงมือเต็มกำลัง','ได้ทั้งหมดหรือเสียมาก'],safe:['เลือกทางที่ทุกคนรอดก่อน','ปลอดภัยกว่า'],sec:['lbreak','ใช้ความจำว่าเกตนี้วนเวลาแบบเดียวกับลูป'],
  p:{gf:['x8h_school','x8h_kids','x8h_scar'],gr:['x8h_kids','x8h_kids','x8h_scar'],wc:['x8h_reform','x8h_reform','x8h_blame'],ws:['x8h_found','x8h_found','x8h_scar'],lt:['x8h_crowd','x8h_kids','x8h_blame'],lb:['x8h_reform','x8h_blame','x8h_blame']}},
 ends:{x8h_school:['S','ปิดเกตโรงเรียนด้วยมือตัวเอง','คุณฟันแกนเกตขาดตรงหน้ากระดานดำ เด็กทั้งสามออกมาพร้อมกัน สมาคมลงโทษคุณหนึ่งปี แล้วมอบเหรียญกล้าหาญในปีถัดไป'],x8h_kids:['A','พาเด็กออกมาครบ','เด็กทั้งหมดออกมาได้ เกตถูกปิดโดยทีมอื่น แต่พ่อแม่ทุกคนจำชื่อคุณได้'],x8h_scar:['C','รอยแผลจากไม้เรียว','คุณรอดออกมาพร้อมแผลเป็นยาวที่ฝ่ามือ และฝันถึงห้องเรียนนั้นทุกคืน'],x8h_reform:['A','กฎปิดล้อมฉบับใหม่','สมาคมแก้กฎให้ฮันเตอร์ท้องถิ่นเข้าช่วยพลเรือนได้ในชั่วโมงแรก กฎนี้ถูกเรียกตามชื่อโรงเรียนคุณ'],x8h_found:['A','เด็กบนชิงช้า','คุณพาเด็กคนที่สามกลับบ้าน เขาโตมาเป็นฮันเตอร์ และใช้ชื่อคุณเป็นชื่อกลางของลูก'],x8h_crowd:['A','ทีมคนแปลกหน้าที่กลายเป็นกิลด์','สิบสองคนที่ไม่รู้จักกันออกมาครบทุกคน แล้วจดทะเบียนกิลด์ด้วยกันในสัปดาห์ถัดไป'],x8h_blame:['C','ถูกโทษว่าก่อความวุ่นวาย','มีคนเจ็บจากความวุ่นวายหน้ารั้ว ใบอนุญาตของคุณถูกพักสองปี']}});

// =================================================== 🌃 ใต้ดิน
A('u_ledger',{w:'under',ic:'📒',n:'บัญชีเล่มดำ',st:M=>M.U&&M.U.inf>=35,
 a0:['บัญชีเล่มดำ','เฮียหมู นักบัญชีของก๊กที่ทำงานมาสามสิบปี หัวใจวายตายบนโต๊ะคิดเงิน คุณเป็นคนแรกที่เข้าไปในห้อง และเห็นสมุดปกดำเล่มหนึ่งในลิ้นชักที่ไม่มีกุญแจ ข้างในเป็นรายชื่อคนรับซองทุกเดือน มีทั้งสารวัตร นายก อบต. และ ส.ส. สองคน',[
  ['🃏 เก็บไว้เป็นไพ่ตาย','อำนาจมหาศาล อันตรายมหาศาล','k',M=>{M.U.heat=Math.min(100,M.U.heat+10)}],['🔥 เผาทิ้งทันที','ไม่มีใครเชื่อว่าคุณเผา','b'],['📰 ส่งให้นักข่าวสายสืบสวน','ทางที่ไม่มีวันกลับ','j']]],
 a1:{k:['บ้านแม่ถูกค้น','มีคนบุกค้นบ้านแม่ที่ต่างจังหวัดตอนกลางวัน ไม่ได้เอาอะไรไปเลย แค่รื้อทุกลิ้นชัก แล้วทิ้งรูปคุณตอนเด็กไว้กลางโต๊ะ',[['🤝 ใช้สมุดต่อรองกับคนข้างบน','เล่นเกมของผู้ใหญ่','n'],['🚐 ย้ายแม่หนีไปอยู่ที่อื่น','ปกป้องคนที่รักก่อน','m',M=>mwFx({mon:-money(M,3)})]]],
  b:['ไม่มีใครเชื่อว่าเผา','พี่ใหญ่เรียกคุณไปนั่งกินข้าว แล้ววางปืนไว้ข้างจาน "ลื้อเผาจริง อั๊วเชื่อ แต่คนอื่นไม่เชื่อ ลื้อต้องพิสูจน์"',[['🩸 รับงานสกปรกเพื่อพิสูจน์ความภักดี','ไม่มีทางถอย','d',M=>{M.U.inf+=10;M.U.heat=Math.min(100,M.U.heat+15)}],['🚶 ขอออกจากวงการ','อาจไม่ได้เดินออกไป','o']]],
  j:['นักข่าวหายตัว','สามวันหลังคุณส่งสมุด นักข่าวคนนั้นหายไปพร้อมรถ บรรณาธิการโทรมาถามว่าคุณเก็บสำเนาไว้หรือเปล่า',[['🔍 ออกตามหานักข่าวเอง','ใช้เส้นสายใต้ดิน','f'],['🌐 ปล่อยสำเนาสู่โซเชียลทั้งหมด','ทั้งประเทศจะรู้','s']]]},
 a2:{t:'คืนที่สมุดเล่มดำเปิดออก',x:{kn:'ส.ส. คนหนึ่งนัดคุณที่ห้องคาราโอเกะชั้นบนสุด บอดี้การ์ดยืนเต็มห้อง เขาวางเช็คเปล่าไว้บนโต๊ะ',km:'แม่ไม่ยอมย้าย "บ้านนี้พ่อแกสร้าง แม่จะตายที่นี่" รถตู้สีดำจอดอยู่ปากซอยมาสามคืนแล้ว',bd:'งานสุดท้ายคือ "คุยกับ" เจ้าของร้านทองที่ไม่ยอมจ่าย เขามีลูกสาวอายุเท่าน้องสาวคุณ',bo:'พี่ใหญ่เดินมาส่งคุณถึงประตูร้านน้ำชา มือขวาอยู่ในกระเป๋าเสื้อ',jf:'คุณเจอรถนักข่าวในโกดังริมแม่น้ำ มีเสียงเคาะจากท้ายรถ และมีคนเฝ้าสี่คน',js:'แฮชแท็กชื่อสมุดขึ้นอันดับหนึ่ง ทีวีทุกช่องพูดเรื่องเดียวกัน แต่คนในก๊กรู้แล้วว่าใครเป็นคนปล่อย'},
  risk:['เดินหน้าเต็มตัว ไม่มีถอย','ชนะทั้งหมดหรือเสียทั้งหมด'],safe:['ถอยครึ่งก้าว เก็บทางหนีไว้','รอดแน่กว่า'],sec:['x8n_truth','ใช้วิธีที่เคยกู้ชื่อตัวเองจากคลิปเดียว'],
  p:{kn:['x8u_ledger','x8u_deal','x8u_gone'],km:['x8u_mom','x8u_mom','x8u_gone'],bd:['x8u_spare','x8u_dirty','x8u_dirty'],bo:['x8u_out','x8u_out','x8u_gone'],jf:['x8u_press','x8u_press','x8u_gone'],js:['x8u_scandal','x8u_witness','x8u_gone']}},
 ends:{x8u_ledger:['S','คนที่ถือชื่อทุกคนไว้ในมือ','คุณฉีกเช็คต่อหน้า ส.ส. แล้วบอกว่าสมุดจะอยู่กับคุณตลอดไป ตั้งแต่คืนนั้น ไม่มีใครในจังหวัดกล้าแตะคนคุณ'],x8u_deal:['B','ขายสมุดแลกอนาคต','คุณได้เงินพอจะไม่ต้องทำงานอีกเลย และรู้ว่าตัวเองเป็นหนึ่งในชื่อที่ถูกเขียนต่อในสมุดเล่มใหม่'],x8u_gone:['C','หายไปเหมือนสมุด','วันหนึ่งคุณออกจากบ้านแล้วไม่ได้กลับมา คนในย่านไม่มีใครพูดชื่อคุณอีก'],x8u_mom:['B','พาแม่ไปให้พ้น','คุณอุ้มแม่ขึ้นรถตอนตีสาม ไปอยู่ทางใต้ แม่บ่นทุกวันว่าคิดถึงบ้าน แต่แม่ยังอยู่'],x8u_spare:['A','ไม่ลงมือกับร้านทอง','คุณกลับมามือเปล่าแล้วบอกพี่ใหญ่ว่าเจ้าของร้านจ่ายแล้ว เงินที่จ่ายเป็นเงินของคุณเอง ลูกสาวร้านทองไม่เคยรู้'],x8u_dirty:['C','มือที่ล้างไม่ออก','คุณพิสูจน์ความภักดีได้ ก๊กเชื่อใจคุณ และคุณไม่กล้ามองหน้าน้องสาวตัวเองอีก'],x8u_out:['A','ออกมาโดยไม่ติดค้างใคร','พี่ใหญ่ดึงมือออกจากกระเป๋า ในมือเป็นซองเงิน "ไปตั้งตัวซะ" คุณไม่เคยกลับไปย่านนั้นอีก'],x8u_press:['A','ช่วยนักข่าวออกจากท้ายรถ','นักข่าวรอดออกมา บทความของเธอได้รางวัลข่าวยอดเยี่ยม แหล่งข่าวนิรนามในเครดิตคือคุณ'],x8u_scandal:['S','คดีที่สะเทือนทั้งประเทศ','มีคนถูกจับสามสิบเอ็ดคน ตำรวจพยานคุ้มครองพาคุณไปอยู่ที่ใหม่ด้วยชื่อใหม่ และคุณได้นอนหลับสนิทครั้งแรกในรอบสิบปี'],x8u_witness:['B','พยานในโครงการคุ้มครอง','คุณให้การในศาล ได้ชื่อใหม่ บ้านใหม่ และไม่มีเพื่อนเก่าสักคน']}});

A('u_boxer',{w:'under',ic:'🥊',n:'มวยรองบ่อน',st:M=>M.U&&S.age>=20&&S.age<=55,
 a0:['เด็กในค่ายมวยใต้ดิน','ไอ้แดง เด็กอายุสิบเจ็ดจากอีสาน ชกที่ลานจอดรถใต้ดินมาสิบไฟต์ไม่เคยแพ้ มันขอให้คุณเป็นพี่เลี้ยงเพราะ "พี่ไม่เคยโกงเงินผม" คืนนี้โปรโมเตอร์สั่งให้มันล้มยกสาม เพราะมีคนแทงข้างตรงข้ามไว้หลายล้าน',[
  ['🎲 บอกให้มันล้มตามสั่ง','ไม่มีปัญหากับเจ้าบ่อน','x',M=>mwFx({mon:money(M,3)})],['🔥 ปล่อยให้มันชกจริง','เจ้าบ่อนขาดทุนแน่','r'],['🚪 พามันหนีไปค่ายมวยที่ถูกกฎหมาย','เริ่มใหม่ที่ศูนย์','e']]],
 a1:{x:['ยกสามที่ไม่มีใครบอกคู่ชก','ไอ้แดงยอมลดการ์ดยกสาม แต่คู่ชกไม่รู้ว่ามีการล้มมวย หมัดสุดท้ายทำให้มันหมดสติไปสองวัน หมอบอกว่ากะโหลกร้าว',[['🏥 จ่ายค่ารักษาทั้งหมด','เงินหายเกลี้ยง','p',M=>mwFx({mon:-money(M,4)})],['🚶 ทิ้งไว้ให้ค่ายจัดการ','ไม่ใช่ความผิดคุณ','a']]],
  r:['เจ้าบ่อนขาดทุนสี่ล้าน','ไอ้แดงชนะน็อกยกสอง ลานจอดรถเงียบกริบ เช้าวันรุ่งขึ้นรถเก๋งสีดำจอดหน้าห้องเช่าคุณ',[['👊 สู้กลับ ใช้คนคุณ','สงครามย่านย่อม','f',M=>{M.U.heat=Math.min(100,M.U.heat+15)}],['💵 ไปขอชดใช้ด้วยตัวเอง','ก้มหัวให้','c',M=>mwFx({mon:-money(M,5)})]]],
  e:['ค่ายถูกกฎหมายที่มีคนตาม','ค่ายมวยในเมืองรับไอ้แดง เทรนเนอร์บอกว่าฝีมือระดับเข็มขัด แต่โปรโมเตอร์ใต้ดินส่งคนมานั่งดูหน้าค่ายทุกวัน',[['👮 ไปแจ้งความ','เข้าระบบ','l'],['🏕️ ซ่อนมันไว้ค่ายต่างจังหวัด','ห่างจากเมือง','h']]]},
 a2:{t:'กระดิ่งยกสุดท้าย',x:{xp:'ไอ้แดงฟื้นแล้ว นั่งมองมือตัวเองที่สั่น มันถามคุณว่า "ผมยังชกได้อีกไหม"',xa:'ข่าวว่าค่ายโยนไอ้แดงกลับบ้านพร้อมเงินสามพัน แม่ของมันโทรหาคุณจากเบอร์ที่ไอ้แดงจดไว้ให้',rf:'สองก๊กยืนเผชิญหน้ากันที่ลานจอดรถใต้ดินเดิม ไอ้แดงยืนอยู่ข้างคุณ ทั้งที่คุณบอกให้มันกลับบ้าน',rc:'เจ้าบ่อนนับเงินที่คุณเอามาให้ แล้วบอกว่ายังขาด "ให้ไอ้แดงชกให้อั๊วอีกสามไฟต์"',el:'คดีขึ้นศาล โปรโมเตอร์ถูกจับ แต่ลูกน้องของเขายังอยู่ข้างนอก วันชิงเข็มขัดของไอ้แดงคือสัปดาห์หน้า',eh:'ห้าปีผ่านไป ไอ้แดงได้สิทธิ์ชิงแชมป์โลกที่ญี่ปุ่น มันขอให้คุณนั่งมุมเวทีให้'},
  risk:['ยืนข้างไอ้แดงจนกระดิ่งสุดท้าย','ทุกอย่างหรือไม่มีอะไร'],safe:['ปกป้องชีวิตก่อนชัยชนะ','ปลอดภัย'],
  p:{xp:['x8u_debt','x8u_debt','x8u_cold'],xa:['x8u_debt','x8u_cold','x8u_cold'],rf:['x8u_king','x8u_truce','x8u_lostboy'],rc:['x8u_truce','x8u_truce','x8u_lostboy'],el:['x8u_champ','x8u_champ','x8u_lostboy'],eh:['x8u_belt','x8u_champ','x8u_champ']}},
 ends:{x8u_debt:['B','ชดใช้ให้เด็กที่สั่งล้ม','ไอ้แดงไม่ได้ชกอีก คุณส่งเงินให้มันเปิดร้านข้าวมันไก่ที่บ้านเกิด ทุกปีใหม่มันส่งไก่มาให้หนึ่งตัว'],x8u_cold:['C','เงินที่ได้จากหมัดคนอื่น','คุณรวยขึ้นจากคืนนั้น และไม่เคยรับสายแม่ของไอ้แดงเลย'],x8u_king:['A','ยึดลานใต้ดินทั้งลาน','ก๊กของเจ้าบ่อนแตก ลานมวยใต้ดินกลายเป็นของคุณ และกฎข้อแรกที่คุณตั้งคือห้ามล้มมวย'],x8u_truce:['B','สงบศึกแลกสามไฟต์','ไอ้แดงชกให้เจ้าบ่อนครบสามไฟต์แล้วเป็นอิสระ ทุกคนเจ็บแต่ไม่มีใครตาย'],x8u_lostboy:['C','เด็กที่ไม่ได้กลับบ้าน','ไอ้แดงหายไปในคืนหนึ่ง คุณเก็บนวมคู่แรกของมันไว้ใต้เตียง'],x8u_champ:['A','เข็มขัดเส้นแรก','ไอ้แดงได้เข็มขัดแชมป์ประเทศ มันยกเข็มขัดชี้มาที่มุมเวทีของคุณ'],x8u_belt:['S','แชมป์โลกจากลานจอดรถ','กระดิ่งยกสิบสองดังขึ้น กรรมการยกมือไอ้แดง ทั้งโลกได้ยินมันพูดชื่อคุณเป็นคนแรกในการสัมภาษณ์']}});

