A('t_fall',{w:'tower',ic:'🪂',n:'คนที่ลงมาจากยอด',st:M=>M.TW&&M.TW.fl>=30&&!M.TW.fin,
 a0:['คนที่ลงมาจากยอด','ชายแก่ผมขาวเดินลงบันไดจากชั้นบนสุด ไม่มีบัตรนักปีน ไม่มีอุปกรณ์ เขาบอกว่าขึ้นถึงชั้นร้อยมาตั้งแต่สามสิบปีก่อน และข้างบนไม่ได้มีพรอย่างที่ป้ายบอก ทุกสำนักข่าวพยายามสัมภาษณ์เขา แต่เขาขอคุยกับคุณคนเดียว',[
  ['👂 ฟังเขาคนเดียว','ความลับที่ไม่มีใครรู้','l'],['📺 พาเขาออกสื่อ','ทุกคนควรรู้','m'],['🧪 ส่งให้สมาคมตรวจสอบ','อาจเป็นคนบ้า','a']]],
 a1:{l:['สิ่งที่อยู่ชั้นร้อย','ชายแก่เล่าว่าชั้นร้อยมีห้องสีขาวและเก้าอี้ คนที่ขอพรจะต้องนั่งเก้าอี้นั้นแทนคนก่อนหน้า และกลายเป็นเสียงที่ถามคนต่อไป เขานั่งอยู่สามสิบปีจนมีคนขอให้ "ทุกคนได้กลับบ้าน" เขาจึงได้ลงมา',[['🧗 ขึ้นไปดูให้เห็นกับตา','ปีนต่อ','c'],['🛑 เลิกปีน ไม่อยากไปนั่งเก้าอี้นั้น','ชีวิตสำคัญกว่า','q']]],
  m:['ทั้งโลกสั่นสะเทือน','คลิปสัมภาษณ์มีคนดูพันล้าน นักปีนครึ่งหนึ่งเลิกปีน อีกครึ่งบอกว่าเขาโกหก ชายแก่หายตัวไปจากโรงพยาบาลในคืนที่สาม',[['🔍 ตามหาชายแก่','อาจมีคนไม่อยากให้เขาพูด','f'],['🧗 พิสูจน์ด้วยการปีนเอง','คำตอบอยู่ข้างบน','p']]],
  a:['รายงานของสมาคม','สมาคมแถลงว่าชายแก่เป็นผู้ป่วยจิตเวช แต่ลายนิ้วมือของเขาตรงกับนักปีนที่หายไปเมื่อสามสิบปีก่อน และเขายังหนุ่มอยู่ในรูปถ่ายใบสุดท้าย',[['📂 ขโมยแฟ้มของสมาคม','ผิดกฎหมาย','s'],['🤝 ยอมรับคำแถลง','ปลอดภัย','k']]]},
 a2:{t:'เก้าอี้ตัวเดียว',x:{lc:'คุณมาถึงชั้นร้อย ห้องสีขาว เก้าอี้ว่างอยู่ ไม่มีเสียงถามอะไรเลย มีแค่รอยเท้าเล็กๆ ของใครบางคนที่เพิ่งลุกออกไป',lq:'คุณวางเชือก แต่ชายแก่มาหาที่บ้าน เขาบอกว่าเก้าอี้ว่างแล้ว และถ้าไม่มีใครนั่ง หอคอยจะเริ่มพัง',mf:'คุณเจอชายแก่ในห้องใต้ดินของสมาคม เขายังมีชีวิต และขอให้คุณพาเขากลับไปที่ชั้นร้อย',mp:'นักปีนทั่วโลกปีนตามคุณขึ้นไป คุณนำหน้าเป็นคนแรก',as:'แฟ้มบอกว่าสมาคมรู้มาตลอดว่าเก้าอี้คืออะไร และกำลังคัดคนที่จะส่งขึ้นไปนั่งคนต่อไป ชื่อคุณอยู่ในรายชื่อ',ak:'หนึ่งปีต่อมา สมาคมมอบตำแหน่งหัวหน้านักปีนให้คุณ พร้อมภารกิจพาทีมขึ้นชั้นร้อย'},
  risk:['นั่งลงบนเก้าอี้','กลายเป็นเสียงของหอคอย'],safe:['ไม่นั่ง หาทางอื่น','อาจไม่มีทางอื่น'],sec:['x8l_write','เขียนกฎใหม่ให้เก้าอี้แบบที่เขียนวิธีออกจากลูป'],
  p:{lc:['x8t_chair','x8t_empty','x8t_crumble'],lq:['x8t_chair','x8t_empty','x8t_crumble'],mf:['x8t_old','x8t_empty','x8t_crumble'],mp:['x8t_many','x8t_empty','x8t_crumble'],as:['x8t_expose','x8t_empty','x8t_chair'],ak:['x8t_many','x8t_empty','x8t_chair']}},
 ends:{x8t_chair:['A','เสียงในห้องสีขาว','คุณนั่งลง แล้วกลายเป็นเสียงที่ถามว่า "ต้องการอะไร" คุณจะรอคนที่ขอให้ทุกคนได้กลับบ้าน'],x8t_empty:['B','เก้าอี้ที่ไม่มีใครนั่ง','หอคอยยังตั้งอยู่ ไม่มีใครนั่งเก้าอี้นั้นอีก และไม่มีใครได้พรอีกเลย'],x8t_crumble:['C','หอคอยที่เริ่มพัง','รอยร้าวปรากฏทั่วหอคอย นักปีนหลายร้อยคนติดอยู่ข้างใน'],x8t_old:['A','พาชายแก่กลับขึ้นไป','ชายแก่นั่งเก้าอี้อีกครั้งด้วยความเต็มใจ เขาบอกว่าข้างบนเงียบดี และขอบคุณที่ให้เขาได้กินข้าวมันไก่ก่อนกลับ'],x8t_many:['S','เก้าอี้ที่แบ่งกันนั่ง','นักปีนร้อยคนตกลงผลัดกันนั่งคนละปี เสียงของหอคอยเปลี่ยนทุกปี และพรก็ไม่เคยมีราคาเป็นชีวิตใครอีก'],x8t_expose:['S','รายชื่อของสมาคม','คุณเปิดแฟ้มต่อสาธารณะ ผู้บริหารสมาคมลาออกทั้งชุด และไม่มีใครถูกส่งขึ้นไปนั่งโดยไม่เต็มใจอีก']}});

