 const nz=()=>{zw=(z0||.28)-((z0||.28)-(z1||.1))*(k/Math.max(1,N-1));zx=.05+Math.random()*(.9-zw);Z.style.left=zx*100+'%';Z.style.width=zw*100+'%';s.textContent=`รอบ ${k+1}/${N} · โดนเป้า ${hit}`};nz();
 tm=setInterval(()=>{x+=d*.012*sp0*(1+k*.12);if(x>=1){x=1;d=-1}if(x<=0){x=0;d=1}Nd.style.left=`calc(${x*100}% - 2px)`},16);
